29	#include <config.h>
30	
31	#include "idn2.h"
32	
33	#include <errno.h>		/* errno */
34	#include <stdlib.h>		/* malloc, free */
35	
36	#include "punycode.h"
37	
38	#include <unitypes.h>
39	#include <uniconv.h>		/* u8_strconv_from_locale */
40	#include <unistr.h>		/* u8_to_u32, u32_cpy, ... */
41	
42	/**
43	 * idn2_to_unicode_8z4z:
44	 * @input: Input zero-terminated UTF-8 string.
45	 * @output: Newly allocated UTF-32/UCS-4 output string.
46	 * @flags: Currently unused.
47	 *
48	 * Converts a possibly ACE encoded domain name in UTF-8 format into a
49	 * UTF-32 string (punycode decoding). The output buffer will be zero-terminated
50	 * and must be deallocated by the caller.
51	 *
52	 * @output may be NULL to test lookup of @input without allocating memory.
53	 *
54	 * Returns:
55	 *   %IDN2_OK: The conversion was successful.
56	 *   %IDN2_TOO_BIG_DOMAIN: The domain is too long.
57	 *   %IDN2_TOO_BIG_LABEL: A label is would have been too long.
58	 *   %IDN2_ENCODING_ERROR: Character conversion failed.
59	 *   %IDN2_MALLOC: Memory allocation failed.
60	 *
61	 * Since: 2.0.0
62	 **/
63	int
64	idn2_to_unicode_8z4z (const char * input, uint32_t ** output, G_GNUC_UNUSED int flags)
65	{
66	  uint32_t *domain_u32;
67	  int rc;
68	
69	  if (!input)
70	    {
71	      if (output)
72		*output = NULL;
73	      return IDN2_OK;
74	    }
75	
76	  /* split into labels and check */
77	  uint32_t out_u32[IDN2_DOMAIN_MAX_LENGTH + 1];
78	  size_t out_len = 0;
79	  const char *e, *s;
80	
81	  for (e = s = input; *e; s = e)
82	    {
83	      uint32_t label_u32[IDN2_LABEL_MAX_LENGTH];
84	      size_t label_len = IDN2_LABEL_MAX_LENGTH;
85	
86	      while (*e && *e != '.')
87		e++;
88	
89	      if (e - s >= 4 && (s[0] == 'x' || s[0] == 'X')
90		  && (s[1] == 'n' || s[1] == 'N')
91		  && s[2] == '-' && s[3] == '-')
92		{
93		  s += 4;
94	
95		  rc =
96		    _idn2_punycode_decode (e - s, (char *) s, &label_len, label_u32);
97		  if (rc)
98		    return rc;
99	
100		  if (out_len + label_len + (*e == '.') > IDN2_DOMAIN_MAX_LENGTH)
101		    return IDN2_TOO_BIG_DOMAIN;
102	
103		  u32_cpy (out_u32 + out_len, label_u32, label_len);
104		}
105	      else
106	        {
107		  /* convert UTF-8 input to UTF-32 */
108		  if (!(domain_u32 = u8_to_u32 ((uint8_t*)s, e - s, NULL, &label_len)))
109		    {
110		      if (errno == ENOMEM)
111			return IDN2_MALLOC;
112		      return IDN2_ENCODING_ERROR;
113		    }
114	
115		  if (label_len > IDN2_LABEL_MAX_LENGTH)
116		    {
117		      free (domain_u32);
118		      return IDN2_TOO_BIG_LABEL;
119		    }
120	
121		  if (out_len + label_len + (*e == '.') > IDN2_DOMAIN_MAX_LENGTH)
122		    {
123		      free (domain_u32);
124		      return IDN2_TOO_BIG_DOMAIN;
125		    }
126	
127		  u32_cpy (out_u32 + out_len, domain_u32, label_len);
128		  free (domain_u32);
129		}
130	
131	      out_len += label_len;
132	      if (*e)
133		{
134		  out_u32[out_len++] = '.';
135		  e++;
136		}
137	    }
138	
139	  if (output)
140	    {
141	      uint32_t *_out;
142	
143	      out_u32[out_len] = 0;
144	
145	      _out = u32_cpy_alloc (out_u32, out_len + 1);
146	      if (!_out)
147	        {
148		  if (errno == ENOMEM)
149		    return IDN2_MALLOC;
150		  return IDN2_ENCODING_ERROR;
151		}
152	
153	      *output = _out;
154	    }
155	
156	  return IDN2_OK;
157	}
158	
159	/**
160	 * idn2_to_unicode_4z4z:
161	 * @input: Input zero-terminated UTF-32 string.
162	 * @output: Newly allocated UTF-32 output string.
163	 * @flags: Currently unused.
164	 *
165	 * Converts a possibly ACE encoded domain name in UTF-32 format into a
166	 * UTF-32 string (punycode decoding). The output buffer will be zero-terminated
167	 * and must be deallocated by the caller.
168	 *
169	 * @output may be NULL to test lookup of @input without allocating memory.
170	 *
171	 * Returns:
172	 *   %IDN2_OK: The conversion was successful.
173	 *   %IDN2_TOO_BIG_DOMAIN: The domain is too long.
174	 *   %IDN2_TOO_BIG_LABEL: A label is would have been too long.
175	 *   %IDN2_ENCODING_ERROR: Character conversion failed.
176	 *   %IDN2_MALLOC: Memory allocation failed.
177	 *
178	 * Since: 2.0.0
179	 **/
180	int
181	idn2_to_unicode_4z4z (const uint32_t * input, uint32_t ** output, int flags)
182	{
183	  uint8_t *input_u8;
184	  uint32_t *output_u32;
185	  size_t length;
186	  int rc;
187	
188	  if (!input)
189	    {
190	      if (output)
191		*output = NULL;
192	      return IDN2_OK;
193	    }
194	
195	  input_u8 = u32_to_u8 (input, u32_strlen(input) + 1, NULL, &length);
196	  if (!input_u8)
197	    {
198	      if (errno == ENOMEM)
199		return IDN2_MALLOC;
200	      return IDN2_ENCODING_ERROR;
201	    }
202	
203	  rc = idn2_to_unicode_8z4z ((char*)input_u8, &output_u32, flags);
204	  free (input_u8);
205	
206	  if (rc == IDN2_OK)
207	    {
208	      if (output)
209		*output = output_u32;
210	      else
211		free(output_u32);
212	    }
213	
214	  return rc;
215	}
216	
217	/**
218	 * idn2_to_unicode_44i:
219	 * @in: Input array with UTF-32 code points.
220	 * @inlen: number of code points of input array
221	 * @out: output array with UTF-32 code points.
222	 * @outlen: on input, maximum size of output array with UTF-32 code points,
223	 *          on exit, actual size of output array with UTF-32 code points.
224	 * @flags: Currently unused.
225	 *
226	 * The ToUnicode operation takes a sequence of UTF-32 code points
227	 * that make up one domain label and returns a sequence of UTF-32
228	 * code points. If the input sequence is a label in ACE form, then the
229	 * result is an equivalent internationalized label that is not in ACE
230	 * form, otherwise the original sequence is returned unaltered.
231	 *
232	 * @output may be NULL to test lookup of @input without allocating memory.
233	 *
234	 * Returns:
235	 *   %IDN2_OK: The conversion was successful.
236	 *   %IDN2_TOO_BIG_DOMAIN: The domain is too long.
237	 *   %IDN2_TOO_BIG_LABEL: A label is would have been too long.
238	 *   %IDN2_ENCODING_ERROR: Character conversion failed.
239	 *   %IDN2_MALLOC: Memory allocation failed.
240	 *
241	 * Since: 2.0.0
242	 **/
243	int
244	idn2_to_unicode_44i (const uint32_t * in, size_t inlen, uint32_t * out, size_t * outlen, int flags)
245	{
246	  uint32_t *input_u32;
247	  uint32_t *output_u32;
248	  size_t len;
249	  int rc;
250	
251	  if (!in)
252	    {
253	      if (outlen)
254		*outlen = 0;
255	      return IDN2_OK;
256	    }
257	
258	  input_u32 = (uint32_t *) malloc ((inlen + 1) * sizeof(uint32_t));
259	  if (!input_u32)
260	    return IDN2_MALLOC;
261	
262	  u32_cpy (input_u32, in, inlen);
263	  input_u32[inlen] = 0;
264	
265	  rc = idn2_to_unicode_4z4z (input_u32, &output_u32, flags);
266	  free (input_u32);
267	  if (rc != IDN2_OK)
268	    return rc;
269	
270	  len = u32_strlen (output_u32);
271	  if (out && outlen)
272	    u32_cpy (out, output_u32, len < *outlen ? len : *outlen);
273	  free (output_u32);
274	
275	  if (outlen)
276	    *outlen = len;
277	
278	  return IDN2_OK;
279	}
280	
281	/**
282	 * idn2_to_unicode_8z8z:
283	 * @input: Input zero-terminated UTF-8 string.
284	 * @output: Newly allocated UTF-8 output string.
285	 * @flags: Currently unused.
286	 *
287	 * Converts a possibly ACE encoded domain name in UTF-8 format into a
288	 * UTF-8 string (punycode decoding). The output buffer will be zero-terminated
289	 * and must be deallocated by the caller.
290	 *
291	 * @output may be NULL to test lookup of @input without allocating memory.
292	 *
293	 * Returns:
294	 *   %IDN2_OK: The conversion was successful.
295	 *   %IDN2_TOO_BIG_DOMAIN: The domain is too long.
296	 *   %IDN2_TOO_BIG_LABEL: A label is would have been too long.
297	 *   %IDN2_ENCODING_ERROR: Character conversion failed.
298	 *   %IDN2_MALLOC: Memory allocation failed.
299	 *
300	 * Since: 2.0.0
301	 **/
302	int
303	idn2_to_unicode_8z8z (const char * input, char ** output, int flags)
304	{
305	  uint32_t *output_u32;
306	  uint8_t *output_u8;
307	  size_t length;
308	  int rc;
309	
310	  rc = idn2_to_unicode_8z4z (input, &output_u32, flags);
311	  if (rc != IDN2_OK || !input)
312	    return rc;
313	
314	  output_u8 = u32_to_u8 (output_u32, u32_strlen(output_u32) + 1, NULL, &length);
315	  free (output_u32);
316	
317	  if (!output_u8)
318	    {
319	      if (errno == ENOMEM)
320		return IDN2_MALLOC;
321	      return IDN2_ENCODING_ERROR;
322	    }
323	
324	  if (output)
325	    *output = (char *) output_u8;
326	  else
327	    free (output_u8);
328	
329	  return IDN2_OK;
330	}
331	
332	/**
333	 * idn2_to_unicode_8zlz:
334	 * @input: Input zero-terminated UTF-8 string.
335	 * @output: Newly allocated output string in current locale's character set.
336	 * @flags: Currently unused.
337	 *
338	 * Converts a possibly ACE encoded domain name in UTF-8 format into a
339	 * string encoded in the current locale's character set (punycode
340	 * decoding). The output buffer will be zero-terminated and must be
341	 * deallocated by the caller.
342	 *
343	 * @output may be NULL to test lookup of @input without allocating memory.
344	 *
345	 * Returns:
346	 *   %IDN2_OK: The conversion was successful.
347	 *   %IDN2_TOO_BIG_DOMAIN: The domain is too long.
348	 *   %IDN2_TOO_BIG_LABEL: A label is would have been too long.
349	 *   %IDN2_ENCODING_ERROR: Character conversion failed.
350	 *   %IDN2_MALLOC: Memory allocation failed.
351	 *
352	 * Since: 2.0.0
353	 **/
354	int
355	idn2_to_unicode_8zlz (const char * input, char ** output, int flags)
356	{
357	  int rc;
358	  uint8_t *output_u8, *output_l8;
359	  const char *encoding;
360	
361	  rc = idn2_to_unicode_8z8z (input, (char **) &output_u8, flags);
362	  if (rc != IDN2_OK || !input)
363	    return rc;
364	
365	  encoding = locale_charset ();
366	  output_l8 = (uint8_t*) u8_strconv_to_encoding (output_u8, encoding, iconveh_error);
367	
368	  if (!output_l8)
369	    {
370	      if (errno == ENOMEM)
371	        rc = IDN2_MALLOC;
372	      else
373	        rc = IDN2_ENCODING_ERROR;
374	
375	      free(output_l8);
376	    }
377	  else
378	    {
379	      if (output)
380	        *output = (char *) output_l8;
381	      else
382	        free (output_l8);
383	
384	      rc = IDN2_OK;
385	    }
386	
387	  free (output_u8);
388	
389	  return rc;
390	}
391	
392	/**
393	 * idn2_to_unicode_lzlz:
394	 * @input: Input zero-terminated string encoded in the current locale's character set.
395	 * @output: Newly allocated output string in current locale's character set.
396	 * @flags: Currently unused.
397	 *
398	 * Converts a possibly ACE encoded domain name in the locale's character
399	 * set into a string encoded in the current locale's character set (punycode
400	 * decoding). The output buffer will be zero-terminated and must be
401	 * deallocated by the caller.
402	 *
403	 * @output may be NULL to test lookup of @input without allocating memory.
404	 *
405	 * Returns:
406	 *   %IDN2_OK: The conversion was successful.
407	 *   %IDN2_TOO_BIG_DOMAIN: The domain is too long.
408	 *   %IDN2_TOO_BIG_LABEL: A label is would have been too long.
409	 *   %IDN2_ENCODING_ERROR: Output character conversion failed.
410	 *   %IDN2_ICONV_FAIL: Input character conversion failed.
411	 *   %IDN2_MALLOC: Memory allocation failed.
412	 *
413	 * Since: 2.0.0
414	 **/
415	int
416	idn2_to_unicode_lzlz (const char * input, char ** output, int flags)
417	{
418	  uint8_t *input_l8;
419	  const char *encoding;
420	  int rc;
421	
422	  if (!input)
423	    {
424	      if (output)
425		*output = NULL;
426	      return IDN2_OK;
427	    }
428	
429	  encoding = locale_charset ();
430	  input_l8 = u8_strconv_from_encoding (input, encoding, iconveh_error);
431	
432	  if (!input_l8)
433	    {
434	      if (errno == ENOMEM)
435		return IDN2_MALLOC;
436	      return IDN2_ICONV_FAIL;
437	    }
438	
439	  rc = idn2_to_unicode_8zlz ((char*)input_l8, output, flags);
440	  free (input_l8);
441	
442	  return rc;
443	}
