static int debug = 0;
static int error_count = 0;
static int break_on_error = 0;

_GL_ATTRIBUTE_FORMAT_PRINTF (1, 2) static void
fail (const char *format, ...)
{
  va_list arg_ptr;

  va_start (arg_ptr, format);
  vfprintf (stderr, format, arg_ptr);
  va_end (arg_ptr);
  error_count++;
  if (break_on_error)
    exit (EXIT_FAILURE);
}

static void
ucs4print (const uint32_t * str, size_t len)
{
  size_t i;

  printf ("\t;; ");
  for (i = 0; i < len; i++)
    {
      printf ("U+%04x ", str[i]);
      if ((i + 1) % 4 == 0)
	printf (" ");
      if ((i + 1) % 8 == 0 && i + 1 < len)
	printf ("\n\t;; ");
    }
  puts ("");
}

#include "punycode.h"

int
main (void)
{
  char *p;
  uint32_t *q;
  int rc;
  size_t i, outlen;

  if (!idn2_check_version (IDN2_VERSION))
    fail ("idn2_check_version(%s) failed\n", IDN2_VERSION);

  if (!idn2_check_version (NULL))
    fail ("idn2_check_version(NULL) failed\n");

  if (idn2_check_version ("100.100"))
    fail ("idn2_check_version(\"100.100\") failed\n");

  p = (char *) malloc (sizeof (*p) * BUFSIZ);
  if (p == NULL)
    fail ("malloc() returned NULL\n");

  q = (uint32_t *) malloc (sizeof (*q) * BUFSIZ);
  if (q == NULL)
    fail ("malloc() returned NULL\n");

  for (i = 0; i < sizeof (punycode) / sizeof (punycode[0]); i++)
    {
      if (debug)
	printf ("PUNYCODE entry %d: %s\n", (int) i, punycode[i].name);

      if (debug)
	{
	  printf ("in:\n");
	  ucs4print (punycode[i].in, punycode[i].inlen);
	}

      outlen = BUFSIZ;
      rc = _idn2_punycode_encode (
	punycode[i].inlen, punycode[i].in, &outlen, p);
      if (rc != punycode[i].rc)
	{
	  fail ("punycode_encode() entry %d failed: %d\n", (int) i, rc);
	  if (debug)
	    printf ("FATAL\n");
	  continue;
	}

      if (rc == IDN2_OK)
	p[outlen] = '\0';

      if (debug && rc == IDN2_OK)
	{
	  printf ("computed out: %s\n", p);
	  printf ("expected out: %s\n", punycode[i].out);
	}
      else if (debug)
	printf ("returned %d expected %d\n", rc, punycode[i].rc);

      if (rc == IDN2_OK)
	{
	  if (strlen (punycode[i].out) != strlen (p) ||
	      memcmp (punycode[i].out, p, strlen (p)) != 0)
	    {
	      fail ("punycode() entry %d failed\n", (int) i);
	      if (debug)
		printf ("ERROR\n");
	    }
	  else if (debug)
	    printf ("OK\n\n");
	}
      else if (debug)
	printf ("OK\n\n");

      if (debug)
	{
	  printf ("in: %s\n", punycode[i].out);
	}

      outlen = BUFSIZ;
      rc = _idn2_punycode_decode (strlen (punycode[i].out), punycode[i].out,
				    &outlen, q);
      if (rc != punycode[i].rc)
	{
	  fail ("punycode() entry %d failed: %d\n", (int) i, rc);
	  if (debug)
	    printf ("FATAL\n");
	  continue;
	}

      if (debug && rc == IDN2_OK)
	{
	  printf ("computed out:\n");
	  ucs4print (q, outlen);
	  printf ("expected out:\n");
	  ucs4print (punycode[i].in, punycode[i].inlen);
	}
      else if (debug)
	printf ("returned %d expected %d\n", rc, punycode[i].rc);

      if (rc == IDN2_OK)
	{
	  if (punycode[i].inlen != outlen ||
	      memcmp (punycode[i].in, q, outlen) != 0)
	    {
	      fail ("punycode_decode() entry %d failed\n", (int) i);
	      if (debug)
		printf ("ERROR\n");
	    }
	  else if (debug)
	    printf ("OK\n\n");
	}
      else if (debug)
	printf ("OK\n\n");
    }

  free (q);
  free (p);

  return 0;
}

